import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.D7WGirly.js";const p=JSON.parse('{"title":"Lodestone API & MCP — Advanced Features & Customization","description":"","frontmatter":{},"headers":[],"relativePath":"api-03-advanced-and-customization.md","filePath":"api-03-advanced-and-customization.md"}'),s={name:"api-03-advanced-and-customization.md"};function n(r,e,d,l,u,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="lodestone-api-mcp-—-advanced-features-customization" tabindex="-1">Lodestone API &amp; MCP — Advanced Features &amp; Customization <a class="header-anchor" href="#lodestone-api-mcp-—-advanced-features-customization" aria-label="Permalink to &quot;Lodestone API &amp; MCP — Advanced Features &amp; Customization&quot;">​</a></h1><p><em>Scope strategy, multi-key management, and designing effective AI assistants</em></p><hr><h2 id="scoping-keys-to-the-minimum-required-access" tabindex="-1">Scoping Keys to the Minimum Required Access <a class="header-anchor" href="#scoping-keys-to-the-minimum-required-access" aria-label="Permalink to &quot;Scoping Keys to the Minimum Required Access&quot;">​</a></h2><p>Every API key should carry the minimum scopes needed for its purpose. This principle — least privilege — limits the blast radius if a key is ever compromised.</p><h3 id="practical-scope-examples" tabindex="-1">Practical scope examples <a class="header-anchor" href="#practical-scope-examples" aria-label="Permalink to &quot;Practical scope examples&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Use case</th><th>Recommended scopes</th></tr></thead><tbody><tr><td>Read-only AI assistant for summarizing backlog and roadmaps</td><td><code>features:read</code>, <code>projects:read</code>, <code>releases:read</code></td></tr><tr><td>AI assistant that can also create Features</td><td><code>features:read</code>, <code>features:write</code>, <code>projects:read</code>, <code>releases:read</code></td></tr><tr><td>Full-access assistant for a trusted admin user</td><td><code>*</code> (all scopes)</td></tr><tr><td>External reporting dashboard (read-only)</td><td><code>features:read</code>, <code>projects:read</code>, <code>releases:read</code>, <code>strategies:read</code></td></tr><tr><td>Automated sync from an external system</td><td>Scopes specific to what is being synced</td></tr></tbody></table><p>Never use <code>*</code> (full access) for integrations that only need to read data.</p><hr><h2 id="managing-multiple-api-keys" tabindex="-1">Managing Multiple API Keys <a class="header-anchor" href="#managing-multiple-api-keys" aria-label="Permalink to &quot;Managing Multiple API Keys&quot;">​</a></h2><p>You can generate multiple API keys for a single organization. This is useful when:</p><ul><li>Different tools need different scopes</li><li>Different people or teams need separate keys they can revoke independently</li><li>You&#39;re rotating a key and want to keep the old one active while transitioning</li></ul><p>Each key is listed in Settings &gt; Integrations with its name, a masked key prefix, and its last-used date. Revoke individual keys without affecting others.</p><p><strong>Key rotation best practice:</strong> When rotating a key, generate the new key first and configure the integration to use it before revoking the old key. This prevents downtime.</p><hr><h2 id="designing-effective-ai-assistants-for-lodestone" tabindex="-1">Designing Effective AI Assistants for Lodestone <a class="header-anchor" href="#designing-effective-ai-assistants-for-lodestone" aria-label="Permalink to &quot;Designing Effective AI Assistants for Lodestone&quot;">​</a></h2><p>When building a ChatGPT or Claude assistant powered by the Lodestone API, the instructions you write for the assistant significantly affect how useful it is. A few principles:</p><h3 id="ground-the-assistant-in-your-context" tabindex="-1">Ground the assistant in your context <a class="header-anchor" href="#ground-the-assistant-in-your-context" aria-label="Permalink to &quot;Ground the assistant in your context&quot;">​</a></h3><p>Include your Organization ID and any relevant context directly in the assistant instructions:</p><blockquote><p>&quot;When the user asks about features, always query organization ID <code>abc123</code>. The team uses a 3-level Roadmap hierarchy: Goal → Theme → Feature. Status stages are: Not Started, In Design, In Dev, In QA, Shipped.&quot;</p></blockquote><p>Without this grounding, the assistant will ask for IDs and context on every request, which creates friction.</p><h3 id="define-what-the-assistant-should-and-shouldn-t-do" tabindex="-1">Define what the assistant should and shouldn&#39;t do <a class="header-anchor" href="#define-what-the-assistant-should-and-shouldn-t-do" aria-label="Permalink to &quot;Define what the assistant should and shouldn&#39;t do&quot;">​</a></h3><p>Be explicit in the instructions:</p><blockquote><p>&quot;Do not create, update, or delete any data unless the user explicitly asks you to. Always confirm with the user before making any write operation.&quot;</p></blockquote><p>This prevents the assistant from making unintended changes to your Lodestone data.</p><h3 id="tell-the-assistant-how-to-handle-uncertainty" tabindex="-1">Tell the assistant how to handle uncertainty <a class="header-anchor" href="#tell-the-assistant-how-to-handle-uncertainty" aria-label="Permalink to &quot;Tell the assistant how to handle uncertainty&quot;">​</a></h3><blockquote><p>&quot;If you are unsure which Feature or Release the user is referring to, ask for clarification rather than guessing. If a request would require a scope you don&#39;t have access to, explain that and suggest what the user should do instead.&quot;</p></blockquote><h3 id="common-assistant-patterns-that-work-well" tabindex="-1">Common assistant patterns that work well <a class="header-anchor" href="#common-assistant-patterns-that-work-well" aria-label="Permalink to &quot;Common assistant patterns that work well&quot;">​</a></h3><ul><li><strong>Daily standup assistant</strong> — &quot;What&#39;s in our current Release and what moved to Completed yesterday?&quot;</li><li><strong>Backlog groomer</strong> — &quot;Which Features are missing descriptions? Which have no evaluation scores?&quot;</li><li><strong>Stakeholder prep</strong> — &quot;Summarize our Q2 Roadmap in plain language for a non-technical audience&quot;</li><li><strong>Meeting follow-up</strong> — &quot;I just got off a call where [name] requested [thing]. Create a Feature for this.&quot;</li><li><strong>Status reporter</strong> — &quot;What&#39;s the status of everything in the mobile release?&quot;</li></ul><hr><h2 id="using-the-openapi-spec-with-third-party-tools" tabindex="-1">Using the OpenAPI Spec with Third-Party Tools <a class="header-anchor" href="#using-the-openapi-spec-with-third-party-tools" aria-label="Permalink to &quot;Using the OpenAPI Spec with Third-Party Tools&quot;">​</a></h2><p>The Lodestone OpenAPI specification (<code>/api/v1/openapi</code>) is a standard JSON schema that can be used with:</p><ul><li><strong>Postman / Insomnia</strong> — import as a collection to explore all endpoints and test requests</li><li><strong>Custom code</strong> — use an OpenAPI code generator to produce a type-safe client in your language of choice</li><li><strong>LangChain / LlamaIndex</strong> — load the spec as a tool definition for a programmatic agent pipeline</li><li><strong>Zapier / Make</strong> — use the API module with your Lodestone key to build automated workflows</li></ul><hr><h2 id="understanding-write-operations" tabindex="-1">Understanding Write Operations <a class="header-anchor" href="#understanding-write-operations" aria-label="Permalink to &quot;Understanding Write Operations&quot;">​</a></h2><p>Write operations (endpoints that create or update data) follow the same rules as the Lodestone UI:</p><ul><li>Creating a Feature adds it to the organization&#39;s backlog — it is immediately visible in Lodestone</li><li>Updating a Feature&#39;s status follows the same rules as dragging a card in a Release — the status propagates everywhere</li><li>Creating a Feature does not automatically add it to any Roadmap or Release — you must do that as a separate operation</li><li>Deleting a Feature is not currently exposed via the API — deletions must be done from the Lodestone UI</li></ul><hr><h2 id="rate-limiting-and-reliability" tabindex="-1">Rate Limiting and Reliability <a class="header-anchor" href="#rate-limiting-and-reliability" aria-label="Permalink to &quot;Rate Limiting and Reliability&quot;">​</a></h2><p>The API enforces rate limits on all endpoints. If you build automation that makes many requests in a short period (for example, syncing a large number of Features at once), implement exponential backoff and retry logic.</p><p>Signs you&#39;re being rate-limited:</p><ul><li>HTTP <code>429 Too Many Requests</code> responses</li><li>Requests succeeding intermittently in bursts</li></ul><p>Mitigation strategies:</p><ul><li>Add a small delay between requests in batch operations</li><li>Spread scheduled syncs over time rather than running them all at once</li><li>Cache read responses when the same data is needed multiple times in a short period</li></ul><hr><p><em>Next: Troubleshooting &amp; FAQs — common issues with authentication, scope errors, and AI assistant configuration.</em></p>',46)])])}const m=t(s,[["render",n]]);export{p as __pageData,m as default};
